from decimal import Decimal


def totals_by_customer(orders):
    """Sum the amounts of non-cancelled orders per customer.

    Amounts are converted with ``Decimal`` to avoid binary-float rounding.
    An order is skipped when its status is ``"cancelled"``; an order with no
    status is treated as active. The returned dict is keyed by customer ID in
    ascending customer-ID order.
    """
    totals = {}
    for order in orders:
        if order.get("status", "active") == "cancelled":
            continue
        customer_id = order["customer_id"]
        totals[customer_id] = totals.get(customer_id, Decimal(0)) + Decimal(
            order["amount"]
        )
    return {customer_id: totals[customer_id] for customer_id in sorted(totals)}

