from dataclasses import asdict, is_dataclass


def serialize_user(user):
    """Serialize a User instance into a plain dict of its fields.

    Field names and values are derived from the `schema.User` dataclass
    itself, so the model is defined in exactly one place.
    """
    if not is_dataclass(user):
        raise TypeError(
            f"serialize_user() expects a User dataclass instance, "
            f"got {type(user).__name__}"
        )
    return asdict(user)

